            $script:Icon.Text = 'Jarvis - OFF (Alt+O)'
            $script:Icon.ShowBalloonTip(1500, 'Jarvis', 'Voice assistant is off. Alt+O to turn on.', [System.Windows.Forms.ToolTipIcon]::Info)
        } catch { }
    } else {
